SELECT 
  (SELECT CASE WHEN EXISTS (
    SELECT 1 FROM Player WHERE Name = 'Angelique Kerber' AND Sport = 'Tennis' AND BirthPlace LIKE '%Texas%'
  ) THEN 'True' ELSE 'False' END) AS AngeliqueKerberPlaysTennis,

  (SELECT CASE WHEN EXISTS (
    SELECT 1 FROM Player p
    JOIN Event e ON e.Name = '2005 China Open - Men\'s Doubles'
    JOIN Champion c ON c.PlayerID = p.ID AND c.EventID = e.ID AND c.Year = 2005
    WHERE p.Sport = 'Tennis'
  ) THEN 'True' ELSE 'False' END) AS DefendingChampionPlaysTennis;

