SELECT PostdocInstitution.name, PostdocInstitution.established_year 
FROM Persons AS P
JOIN PostdoctoralTraining AS PT ON P.id = PT.person_id
JOIN Institutions AS PostdocInstitution ON PT.institution_id = PostdocInstitution.id
WHERE P.name = "Theodore Garland, Jr.";

SELECT name, established_year FROM Institutions WHERE name = "Texas Christian University";

SELECT ?otherFilm ?otherFilmReleaseDate WHERE {
  ?otherFilm wdt:P31 wd:Q11424;           # ?otherFilm is a film
             wdt:P161 ?actor;             # ?actor acted in ?otherFilm
             wdt:P577 ?releaseDate.       # ?otherFilm has a release date
  ?actor rdfs:label "Damion Poitier"@en.

  ?sacredPlanet wdt:P31 wd:Q11424;
                rdfs:label "Sacred Planet"@en;
                wdt:P577 ?sacredPlanetReleaseDate.

  FILTER(?otherFilmReleaseDate < ?sacredPlanetReleaseDate)
}
ORDER BY DESC(?otherFilmReleaseDate)

