SELECT ?director ?directorGender WHERE {
  ?film wdt:P31 wd:Q11424;        # instance of film
        rdfs:label "Boxing Helena"@en;
        wdt:P57 ?director.         # director
  ?director wdt:P21 ?directorGender.   # gender property
  FILTER(CONTAINS(LCASE(STR(?director)), "helena") || EXISTS { ?otherDirector wdt:P31 wd:Q11424; wdt:P57 wd:Q180365. }) # to check existence of Martin Scorsese as director
}
